<?php
/** Clickable country directory lands on a real Yii2 detail route. */
use app\services\CountryUi;
$name=CountryUi::name($country);$this->title=$name.'国家资料';$code=strtoupper($country['country_code']);
$map=$country['latitude']!==null&&$country['longitude']!==null?'https://www.openstreetmap.org/?mlat='.(float)$country['latitude'].'&mlon='.(float)$country['longitude'].'#map=5/'.(float)$country['latitude'].'/'.(float)$country['longitude']:null;
?>
<a class="back-link" href="/countries#country-list">← 返回国家探索</a>
<article class="country-profile"><header class="country-profile-head"><div class="country-profile-flag"><?= CountryUi::flag($country) ?></div><div><span><?= e(CountryUi::region($country)) ?> · <?= e($code) ?></span><h1><?= e($name) ?></h1><p><?= e($country['country_name_original']) ?></p></div><?php if($map): ?><a href="<?= e($map) ?>" target="_blank" rel="noopener" class="button outline">在地图中查看 ↗</a><?php endif ?></header>
<div class="country-profile-columns"><section class="card country-fact-card"><div class="card-header"><h2>国家资料</h2></div><dl class="country-fact-list"><div><dt>首都</dt><dd><?= e(CountryUi::capital($country)) ?></dd></div><div><dt>语言</dt><dd><?= e(CountryUi::terms($country['languages'])) ?></dd></div><div><dt>货币</dt><dd><?= e(CountryUi::terms($country['currencies'])) ?></dd></div><div><dt>人口</dt><dd><?= $country['population']!==null?e(number_format((int)$country['population'])).' 人':'—' ?></dd></div><div><dt>面积</dt><dd><?= $country['area_km2']!==null?e(number_format((float)$country['area_km2'])).' 平方公里':'—' ?></dd></div><div><dt>地理坐标</dt><dd><?= e($country['latitude']) ?>°，<?= e($country['longitude']) ?>°</dd></div></dl><?php if($country['source_url']): ?><div class="card-footer"><a href="<?= e(safe_url($country['source_url'])) ?>" target="_blank" rel="noopener">资料来源 ↗</a></div><?php endif ?></section>
<aside class="card country-football"><div class="card-header"><h2>世界杯国家队</h2></div><?php foreach($country['linked_teams'] as $team): ?><div class="card-body"><h3><?= \app\services\TeamUi::label(['code'=>$team['code'],'name'=>$team['name_cn']?:$team['name_original']]) ?></h3><p>2026 世界杯 · 小组 <?= e($team['group_name']) ?></p><a class="button" href="/teams/<?= e($team['slug']) ?>">球队阵容与比赛 ↗</a><a class="country-forum-link" href="/forum?team_id=<?= (int)$team['id'] ?>">进入球队看台 ↗</a></div><?php endforeach ?></aside></div></article>
